window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dae3f4a5b351893e"]={"versions": [{"id": "FIG-dae3f4a5b351893e", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfiguration der RTE-Kalibrierungsunterstützung. Das Diagramm stellt das Zusammenspiel zwischen dem ECU-Configuration-Metamodell (ECUC-Parameter und -Container der RTE) und den M1- bzw. M2-Elementen des Software Component Template (SWC) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>ECUC-Definitionen (RTE-Konfiguration):</strong>\n<ul class=\"fig-list\"><li><code>RteSwComponentType : EcucParamConfContainerDef</code> (Multiplizität 0..*): Übergeordneter Konfigurationscontainer für Software-Komponententypen.\n</li><li><code>RteComponentTypeRef : EcucForeignReferenceDef</code>: Referenzcontainer mit Komposition (<code>+reference</code>) aus <code>RteSwComponentType</code>, verweist via <code>destinationType = SW-COMPONENT-TYPE</code> auf M2-Elemente vom Typ <code>SwComponentType</code>.\n</li><li><code>RteComponentTypeCalibration : EcucParamConfContainerDef</code> (Multiplizität 0..1): Subcontainer von <code>RteSwComponentType</code> (über Komposition <code>+subContainer</code>).\n</li><li><code>RteCalibrationSupportEnabled : EcucBooleanParamDef</code>: Boolescher Konfigurationsparameter, als Komposition <code>+parameter</code> in <code>RteComponentTypeCalibration</code> eingebettet.\n</li><li><code>RteCalibrationSwAddrMethodRef : EcucForeignReferenceDef</code> (Multiplizität 0..*, <code>destinationType = SW-ADDR-METHOD</code>): Referenzcontainer mit Komposition <code>+reference</code> aus <code>RteComponentTypeCalibration</code>, zeigt via Fremdreferenz auf <code>SwAddrMethod</code>.\n</li></ul>\n</li><li><strong>Software Component Template:</strong>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (spezialisiert <code>AtpType</code>, <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>): Basis-Klasse für Komponententypen, spezialisiert durch <code>AtomicSwComponentType</code> und <code>ParameterSwComponentType</code>.\n</li><li><code>SwDataDefProps</code> (mit Stereotyp <code>«atpVariation»</code>): Besitzt eine gerichtete Assoziation <code>+swAddrMethod</code> mit Multiplizität 0..1 zu <code>SwAddrMethod</code>.\n</li><li><code>SwAddrMethod</code> (spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>): Speicheradressierungsmethode, Ziel der Referenz aus <code>RteCalibrationSwAddrMethodRef</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Metamodell-Diagramm ohne Laufzeit- oder Sequenzinteraktionen. Es definiert die deklarativen Konfigurationsstrukturen, über die der RTE-Generator Kalibrierungseigenschaften für Parameter-Softwarekomponenten auflöst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration spezifiziert, wie Kalibrierdaten für <code>ParameterSwComponentType</code> bereitgestellt werden. Ist Kalibrierungsunterstützung über <code>RteCalibrationSupportEnabled</code> aktiviert, steuert <code>RteCalibrationSwAddrMethodRef</code> über die Zuordnung zu <code>SwAddrMethod</code> die Speicherzuweisung und Kalibrierbarkeit der entsprechenden Datenstrukturen in der generierten RTE. Multiplizitäten und Foreign-Reference-Typen erzwingen die formale Validierung im AUTOSAR-Metamodell.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6076f3f72c6703fd", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfiguration der RTE-Kalibrierungsunterstützung. Das Diagramm stellt das Zusammenspiel zwischen dem ECU-Configuration-Metamodell (ECUC-Parameter und -Container der RTE) und den M1- bzw. M2-Elementen des Software Component Template (SWC) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong>ECUC-Definitionen (RTE-Konfiguration):</strong>\n<ul class=\"fig-list\"><li><code>RteSwComponentType : EcucParamConfContainerDef</code> (Multiplizität 0..*): Übergeordneter Konfigurationscontainer für Software-Komponententypen.\n</li><li><code>RteComponentTypeRef : EcucForeignReferenceDef</code>: Referenzcontainer mit Komposition (<code>+reference</code>) aus <code>RteSwComponentType</code>, verweist via <code>destinationType = SW-COMPONENT-TYPE</code> auf M2-Elemente vom Typ <code>SwComponentType</code>.\n</li><li><code>RteComponentTypeCalibration : EcucParamConfContainerDef</code> (Multiplizität 0..1): Subcontainer von <code>RteSwComponentType</code> (über Komposition <code>+subContainer</code>).\n</li><li><code>RteCalibrationSupportEnabled : EcucBooleanParamDef</code>: Boolescher Konfigurationsparameter, als Komposition <code>+parameter</code> in <code>RteComponentTypeCalibration</code> eingebettet.\n</li><li><code>RteCalibrationSwAddrMethodRef : EcucForeignReferenceDef</code> (Multiplizität 0..*, <code>destinationType = SW-ADDR-METHOD</code>): Referenzcontainer mit Komposition <code>+reference</code> aus <code>RteComponentTypeCalibration</code>, zeigt via Fremdreferenz auf <code>SwAddrMethod</code>.\n</li></ul>\n</li><li><strong>Software Component Template:</strong>\n<ul class=\"fig-list\"><li><code>SwComponentType</code> (spezialisiert <code>AtpType</code>, <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>): Basis-Klasse für Komponententypen, spezialisiert durch <code>AtomicSwComponentType</code> und <code>ParameterSwComponentType</code>.\n</li><li><code>SwDataDefProps</code> (mit Stereotyp <code>«atpVariation»</code>): Besitzt eine gerichtete Assoziation <code>+swAddrMethod</code> mit Multiplizität 0..1 zu <code>SwAddrMethod</code>.\n</li><li><code>SwAddrMethod</code> (spezialisiert <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>): Speicheradressierungsmethode, Ziel der Referenz aus <code>RteCalibrationSwAddrMethodRef</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Metamodell-Diagramm ohne Laufzeit- oder Sequenzinteraktionen. Es definiert die deklarativen Konfigurationsstrukturen, über die der RTE-Generator Kalibrierungseigenschaften für Parameter-Softwarekomponenten auflöst.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Konfiguration spezifiziert, wie Kalibrierdaten für <code>ParameterSwComponentType</code> bereitgestellt werden. Ist Kalibrierungsunterstützung über <code>RteCalibrationSupportEnabled</code> aktiviert, steuert <code>RteCalibrationSwAddrMethodRef</code> über die Zuordnung zu <code>SwAddrMethod</code> die Speicherzuweisung und Kalibrierbarkeit der entsprechenden Datenstrukturen in der generierten RTE. Multiplizitäten und Foreign-Reference-Typen erzwingen die formale Validierung im AUTOSAR-Metamodell.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-dae3f4a5b351893e", "to": "FIG-6076f3f72c6703fd", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Typographische Bereinigung in den Kopfzeilen der ECU-C-Definitionsklassen: Das Leerzeichen vor dem Doppelpunkt wurde entfernt bei <code>RteSwComponentType:</code>, <code>RteComponentTypeRef:</code>, <code>RteComponentTypeCalibration:</code>, <code>RteCalibrationSupportEnabled:</code> und <code>RteCalibrationSwAddrMethodRef:</code>.\n</li></ul>"}]};
